fixtures.tests/test_payment.py:
from src.payment import charge

def test_charge_basic():
    assert charge(100) == 101.0

def test_charge_zero_raises():
    import pytest
    with pytest.raises(ZeroDivisionError):
        charge(0)

def test_charge_negative():
    assert charge(50) == 52.0

